import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] firstLine = br.readLine().split(" ");
        int n = Integer.parseInt(firstLine[0]);
        int m = Integer.parseInt(firstLine[1]);
        String[] aLine = br.readLine().split(" ");
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = Integer.parseInt(aLine[i]);
        }

        List<Integer> firstHalf = new ArrayList<>();
        List<Integer> secondHalf = new ArrayList<>();
        int maxModValue = 0;

        int firstHalfSize = (n / 2) + (n % 2);
        int secondHalfSize = n / 2;

        // Generate all subset sums for the first half
        for (int subset = 0; subset < (1 << firstHalfSize); subset++) {
            int totalSum = 0;
            int maskValue = subset;
            for (int i = 0; i < 20; i++) {
                if ((maskValue & 1) == 1 && i < firstHalfSize) {
                    totalSum += a[i];
                }
                maskValue >>= 1;
            }
            firstHalf.add(totalSum % m);
        }
        Collections.sort(firstHalf);

        // Generate all subset sums for the second half
        for (int subset = 0; subset < (1 << secondHalfSize); subset++) {
            int totalSum = 0;
            int maskValue = subset;
            for (int i = 0; i < 20; i++) {
                if ((maskValue & 1) == 1 && i < secondHalfSize) {
                    totalSum += a[firstHalfSize + i];
                }
                maskValue >>= 1;
            }
            totalSum %= m;

            int target = m - totalSum - 1;
            int position = Collections.binarySearch(firstHalf, target);
            if (position < 0) {
                position = -position - 1;
            }

            int candidateValue;
            if (position < firstHalf.size()) {
                candidateValue = firstHalf.get(position);
                if (candidateValue > target && position - 1 >= 0) {
                    candidateValue = firstHalf.get(position - 1);
                }
            } else {
                candidateValue = firstHalf.get(firstHalf.size() - 1);
            }

            maxModValue = Math.max(maxModValue, Math.max((totalSum + candidateValue) % m, (totalSum + firstHalf.get(firstHalf.size() - 1)) % m));
        }

        System.out.println(maxModValue);
    }
}
